#include "ark/model.hpp"
#include "ark/assembly_solver_074b.hpp"
#include "ark/serialize.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
namespace {
using namespace ark;using V=arkjson::Value;size_t checks=0;
void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}const V& at(const V& v,const char* key){auto p=v.find(key);if(!p)throw std::runtime_error(key);return *p;}
struct Mode{AssemblySolveMode074B old;explicit Mode(AssemblySolveMode074B value):old(setAssemblySolveMode074B(value)){}~Mode(){setAssemblySolveMode074B(old);}};
Document fixture(int count){Document d;Feature f;f.name="Shared box";f.type=FeatureType::Box;f.p={{"dx","2"},{"dy","3"},{"dz","4"}};d.addFeature(f);d.recompute();AssemblyNode anchor;anchor.id=1;anchor.feature=1;anchor.name="Anchor";anchor.fixed=true;d.assembly.push_back(anchor);for(int i=0;i<count;++i){AssemblyNode node;node.id=i+2;node.feature=1;node.name="Slider "+std::to_string(i);node.p={{"tx",std::to_string(i*5)}};d.assembly.push_back(node);AssemblyMate mate;mate.id=i+1;mate.a=1;mate.b=node.id;mate.type="distance";mate.reference_a=mate.reference_b="origin";mate.value=std::to_string(10+i);d.mates.push_back(mate);}return d;}
bool solve(Document& d,std::vector<AssemblyPlacement>& values,AssemblyDiagnostics& diagnostics){std::string error;const bool ok=resolveAssembly(d,values,error,&diagnostics);if(!ok)std::cerr<<error<<'\n';return ok;}
void equal(const std::vector<AssemblyPlacement>& a,const std::vector<AssemblyPlacement>& b){check(a.size()==b.size(),"Pose count differs");for(size_t i=0;i<a.size();++i){check(a[i].node==b[i].node&&a[i].feature==b[i].feature,"Pose identities differ");for(int j=0;j<16;++j)check(std::abs(a[i].world.m[j]-b[i].world.m[j])<1e-7,"Incremental pose differs from monolithic cold reference");}}
void compareReference(Document& d,const std::vector<AssemblyPlacement>& actual,const AssemblyDiagnostics& current){Mode cold(AssemblySolveMode074B::ColdReference);std::vector<AssemblyPlacement> expected;AssemblyDiagnostics reference;check(solve(d,expected,reference),"Cold reference rejected valid solve");equal(actual,expected);check(current.rank==reference.rank&&current.freeDofs==reference.freeDofs,"Grouped rank changed old global-scale DOF contract");}
void independent(){clearAssemblySolveCache074B();auto d=fixture(24);std::vector<AssemblyPlacement> poses;AssemblyDiagnostics initial;const auto source=documentToJson(d);check(solve(d,poses,initial),"Initial component solve failed");check(at(initial.solverEvidence,"components").num==24&&at(initial.solverEvidence,"components_solved").num==24,"Independent fixed-anchor mates were not separated");compareReference(d,poses,initial);check(documentToJson(d)==source,"Solving mutated authoring");
 AssemblyDiagnostics repeated;check(solve(d,poses,repeated),"Repeated solve failed");check(at(repeated.solverEvidence,"components_reused").num==24&&at(repeated.solverEvidence,"jacobian_columns").num==0,"Unchanged groups repeated numerical Jacobian work");
 d.mates[0].value="10.1";AssemblyDiagnostics edited;check(solve(d,poses,edited),"Edited group solve failed");check(at(edited.solverEvidence,"components_reused").num==23&&at(edited.solverEvidence,"components_solved").num==1&&at(edited.solverEvidence,"warm_starts").num==1,"Target edit did not warm only its affected affine group");compareReference(d,poses,edited);
 d.assembly[1].p["tx"]="9";AssemblyDiagnostics moved;check(solve(d,poses,moved),"Authored free coordinate edit failed");check(at(moved.solverEvidence,"warm_starts").num==0,"Changed authored pose used stale warm state");check(std::abs(poses[1].world.m[12]-9)<1e-10,"Warm cache erased authored free coordinate");compareReference(d,poses,moved);
 const auto correct=d.mates[0];AssemblyMate conflict=correct;conflict.id=1000;conflict.value="20";d.mates.push_back(conflict);std::vector<AssemblyPlacement> failed;AssemblyDiagnostics report;check(!solve(d,failed,report)&&failed.empty(),"Conflicting group was accepted");{Mode cold(AssemblySolveMode074B::ColdReference);check(!solve(d,failed,report),"Cold reference unexpectedly accepted conflict");}d.mates.pop_back();check(solve(d,poses,report),"Cache did not recover after rejected problem");compareReference(d,poses,report);
 d.assembly[0].fixed=false;check(!solve(d,failed,report),"Unanchored components bypassed grounding checks");
}
void nonlinearAndFallback(){clearAssemblySolveCache074B();auto d=fixture(3);d.mates[0].type="revolute";d.mates[0].value="0";d.assembly[1].p["rz"]="137";d.assembly[1].p["tz"]="4";d.mates[1].type="coincident";d.mates[1].value="0";d.mates[2].type="contact";d.mates[2].value="0";d.assembly[3].p["rx"]="180";std::vector<AssemblyPlacement> poses;AssemblyDiagnostics result;check(solve(d,poses,result),"Nonlinear independent component solve failed");compareReference(d,poses,result);AssemblyDiagnostics again;check(solve(d,poses,again)&&at(again.solverEvidence,"components_reused").num==3,"Exact nonlinear problem should reuse after residual checks");
 // Cross-parent carriers remain the original coupled solver path.
 auto cross=fixture(1);AssemblyNode first;first.id=10;first.name="Fixed carrier";AssemblyNode second;second.id=11;second.name="Moving carrier";cross.assembly[0].parent=10;cross.assembly[1].parent=11;cross.assembly.push_back(first);cross.assembly.push_back(second);check(solve(cross,poses,result),"Cross-parent reference solve failed");check(at(result.solverEvidence,"mode").str=="monolithic_reference_or_fallback","Cross-carrier problem escaped conservative solver");compareReference(cross,poses,result);
}
void rankScale(){auto d=fixture(2);d.mates[0].type="coincident";d.mates[0].value="0";d.assembly[1].p["tx"]="10000";std::vector<AssemblyPlacement> poses;AssemblyDiagnostics result;check(solve(d,poses,result),"Mixed-scale solve failed");compareReference(d,poses,result);}
}
int main(){try{independent();nonlinearAndFallback();rankScale();std::cout<<"074B assembly groups: "<<checks<<" residual, cold-reference, warm-start, DOF, authored-pose and rejection checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
